234:    if(animTime<swingUntil&&!delivery.hit&&delivery.z> -1.65&&delivery.z<.62&&delivery.line==='good')hitBall(Math.max(0,1-Math.abs(delivery.z+.52)/1.82),delivery.z);
235:    if(delivery.z>.75&&!delivery.hit)missBall();
236:  }else if(delivery?.hit&&delivery.launch){
237:    const p=delivery.launch;p.x+=p.vx*dt;p.z+=p.vz*dt;p.y+=p.vy*dt;p.vy-=9.8*dt;
238:    if(p.y<.12){p.y=.12;if(!p.bounce){p.vy=Math.abs(p.vy)*.38;p.vx*=.83;p.vz*=.83;p.bounce=true;}else{p.vy=0;p.vx*=.95;p.vz*=.95;p.grounded=true;}}
239:    ball.position.set(p.x,p.y,p.z);ball.rotation.x+=dt*9;ball.rotation.z+=dt*7;
240:    trail.visible=true;trail.position.set(p.x-p.vx*.045,p.y,p.z-p.vz*.045);trail.scale.y=.8;trail.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),new THREE.Vector3(p.vx,p.vy,p.vz).normalize());
241:    const radial=Math.hypot(p.x,p.z+2);
242:    if(radial>11.25||p.grounded||now/1000-delivery.start>4.5)completeShot();
243:  }else trail.visible=false;
244:  camera.position.x=Math.sin(animTime*.13)*.11;camera.lookAt(0,1.18,-2.2);
245:  renderer.render(scene,camera);
246: }
247: requestAnimationFrame(animate);

